import re
from typing import List, Dict, Any, Tuple

# ------------------------------------------------------------
# Helper functions (assumed to be provided by the sandbox)
# ------------------------------------------------------------
def node_by_title(doc: dict, title: str) -> dict:
    for n in doc["nodes"]:
        if n.get("title") == title:
            return n
    raise KeyError(f"Title {title!r} not found in doc")

def node_by_id(doc: dict, node_id: str) -> dict:
    for n in doc["nodes"]:
        if n.get("node_id") == node_id:
            return n
    raise KeyError(f"Node ID {node_id!r} not found in doc")

def children(doc: dict, node: dict) -> List[dict]:
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def table_rows(node: dict) -> List[Tuple[int, Dict[str, str]]]:
    """Return list of (row_index, {col_name: cell_str})"""
    out = []
    cols = node["table"]["columns"]
    for idx, row in enumerate(node["table"]["rows"]):
        out.append((idx, dict(zip(cols, row))))
    return out

# ------------------------------------------------------------
# Parsing utilities
# ------------------------------------------------------------
NUM_RE = re.compile(r"[-+]?[\d,]+(?:\.\d+)?")
def parse_number(cell: str):
    m = NUM_RE.search(cell)
    if m:
        try:
            return float(m.group(0).replace(",", ""))
        except Exception:
            return None
    return None

def parse_year(col: str):
    try:
        y = int(col.strip())
        return float(y)
    except Exception:
        return None

def desc_to_id(desc: str) -> str:
    return re.sub(r"\s+", "_", desc.strip().lower())

# ------------------------------------------------------------
# Core functions
# ------------------------------------------------------------
def entities(doc: dict, scope: str) -> List[Dict[str, Any]]:
    scnode = node_by_title(doc, scope)
    ents: Dict[str, Dict[str, Any]] = {}
    for child in children(doc, scnode):
        if child.get("kind") != "table":
            continue
        for _, row in table_rows(child):
            label = list(row.values())[0].strip()
            if not label:
                continue
            eid = desc_to_id(label)
            if eid not in ents:
                ents[eid] = {"id": eid, "description": label}
    return list(ents.values())

def recorded_end(doc: dict, scope: str) -> Any:
    scnode = node_by_title(doc, scope)
    max_year: Any = None
    for child in children(doc, scnode):
        if child.get("kind") != "table":
            continue
        for col in child["table"]["columns"]:
            y = parse_year(col)
            if y is not None:
                if max_year is None or y > max_year:
                    max_year = y
    return max_year

def _make_src(node: dict, row_idx: int, cols: List[str]) -> List[Any]:
    """Return src as a list containing a single location"""
    return [[node["node_id"], row_idx, cols]]

def inputs(doc: dict, scope: str) -> List[Dict[str, Any]]:
    scnode = node_by_title(doc, scope)
    outs: List[Dict[str, Any]] = []
    seen: set[tuple] = set()
    for child in children(doc, scnode):
        if child.get("kind") != "table":
            continue
        for row_idx, row in table_rows(child):
            label_cell = list(row.values())[0]
            num = parse_number(label_cell)
            if num is not None:
                eid = desc_to_id(label_cell)
                key = (eid, None)
                if key in seen:
                    continue
                seen.add(key)
                outs.append({
                    "id": eid,
                    "time": None,
                    "kind": "external",
                    "entities": [eid],
                    "fields": {"value": num},
                    "src": _make_src(child, row_idx, [child["table"]["columns"][0]]),
                })
    return outs

def outcomes(doc: dict, scope: str) -> List[Dict[str, Any]]:
    scnode = node_by_title(doc, scope)
    outs: List[Dict[str, Any]] = []
    for child in children(doc, scnode):
        if child.get("kind") != "table":
            continue
        for row_idx, row in table_rows(child):
            label_cell = list(row.values())[0]
            if not label_cell.strip():
                continue
            eid = desc_to_id(label_cell)
            # Check that at least one cell besides label has a number
            has_num = any(
                parse_number(cell) is not None
                for col, cell in row.items()
                if col != child["table"]["columns"][0]
            )
            if not has_num:
                continue
            for col, cell in row.items():
                if col == child["table"]["columns"][0]:
                    continue
                num = parse_number(cell)
                if num is not None:
                    y = parse_year(col)
                    outs.append({
                        "time": y,
                        "kind": "value",
                        "entities": [eid],
                        "value": num,
                        "src": _make_src(child, row_idx, [col]),
                    })
    return outs

def params(doc: dict, scope: str) -> Dict[str, float]:
    # No explicit constants in the excerpts
    return {}

