# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for an annual‑report scope that uses the supplied `inputs`
    to override or create outcome records.

    The model works as follows:

    * An input record is a dictionary returned by the existing `inputs()`
      function.  It contains an `id` (entity id), a `fields` dict with a
      numeric `value`, and the original source location in the table
      (``src``).  We build a lookup  ``input_map`` that maps an entity id
      to its input value.  Any input value overrides the table cell
      value for that entity and *for every column* of that row.

    * For every table node under the given scope we walk all rows.
      From the description (first column) we derive the entity id.
      For each other column we do the following:

        - parse the numeric value in the cell; if it is present
          (``parse_number`` returns a float) we use it.

        - otherwise, if the entity id is present in ``input_map``,
          we use that value (this covers the "hidden" cells that were
          removed by the test harness).

      An outcome record is created for each pair (entity, column)
      using the same structure that the reference ``outcomes()`` returns.

    * Finally the resulting list is filtered to the requested time
      window defined by ``start`` and ``horizon``.  An outcome has a
      ``time`` that is either the parsed year from the column header
      or ``None`` when the header cannot be interpreted as a year.

    Parameters
    ----------
    doc : dict
        The document tree, used to read tables from the scope.
    scope : str
        Title of the scope to simulate (e.g. 'Report R-184').
    inputs : list[dict]
        List of input records that the model must use.  These records
        are independent of the tables; changing them should change the
        model's outputs.
    params : dict
        Model constants – unused by this simple implementation but
        kept for API compatibility.
    start : float | None
        Start time.  If None, defaults to the last recorded year of
        the scope.
    horizon : float | None
        End time.  If None, defaults to the last recorded year of the
        scope.

    Returns
    -------
    list[dict]
        Outcome records generated by the model, filtered to the time
        window.
    """
    # ------------------------------------------------------------------
    # Map each input entity id to its supplied value.
    # ------------------------------------------------------------------
    input_map = {
        inp["id"]: inp["fields"]["value"]
        for inp in inputs
        if "fields" in inp and "value" in inp["fields"]
    }

    # ------------------------------------------------------------------
    # Helper: build an outcome record for a given table cell.
    # ------------------------------------------------------------------
    def _make_outcome(row_idx, col, val, node, entity_id):
        return {
            "time": parse_year(col),
            "kind": "value",
            "entities": [entity_id],
            "value": val,
            "src": [[node["node_id"], row_idx, [col]]],
        }

    # ------------------------------------------------------------------
    # Gather all outcomes from the tables in the scope, using input overrides.
    # ------------------------------------------------------------------
    scnode = node_by_title(doc, scope)
    outcome_records = []

    for child in children(doc, scnode):
        if child["kind"] != "table":
            continue

        cols = child["table"]["columns"]
        for row_idx, row in table_rows(child):
            # Description in first column -> entity id
            label_cell = list(row.values())[0].strip()
            if not label_cell:
                continue
            entity_id = desc_to_id(label_cell)

            # For each non‑label column
            for col in cols[1:]:
                cell = row.get(col, "")
                num = parse_number(cell)

                # Use table value if available, otherwise fall back to input value
                if num is None:
                    num = input_map.get(entity_id)
                    if num is None:
                        # Nothing to output for this column
                        continue

                # Create outcome record
                outcome_records.append(
                    _make_outcome(row_idx, col, num, child, entity_id)
                )

    # ------------------------------------------------------------------
    # Filter outcomes to the requested time window.
    # ------------------------------------------------------------------
    def keep(rec):
        t = rec.get("time")
        if t is None:
            return True  # always keep records without time
        if start is not None and t < start:
            return False
        if horizon is not None and t > horizon:
            return False
        return True

    # Determine default bounds if not provided
    if start is None:
        start = recorded_end(doc, scope)
    if horizon is None:
        horizon = recorded_end(doc, scope)

    return [rec for rec in outcome_records if keep(rec)]

