import re
from typing import List, Dict, Any, Optional

# ----------------------------------------------------------------------
# Helper functions that are already available in the sandbox
# ----------------------------------------------------------------------
# node_by_title, children, table_rows, parse_number, parse_year, desc_to_id

def _entity_from_label(label: str) -> str:
    """Return the entity id derived from the first column label."""
    return desc_to_id(label)

def _src(node: dict, row_idx: int, col: str) -> List[Any]:
    return [[node["node_id"], row_idx, [col]]]

def _outcome(node: dict, row_idx: int, col: str, val: float, entity: str) -> Dict[str, Any]:
    """Build a single outcome record from a numeric cell."""
    time = parse_year(col)
    return {
        "time": time,
        "kind": "value",
        "entities": [entity],
        "value": val,
        "src": _src(node, row_idx, col),
    }

def simulate(doc: dict,
             scope: str,
             inputs: List[Dict[str, Any]],
             params: Dict[str, float],
             start: Optional[float] = None,
             horizon: Optional[float] = None) -> List[Dict[str, Any]]:
    """
    Forward‑simulation of the process recorded in *scope*.

    Parameters
    ----------
    doc : dict
        The document describing all excerpts.
    scope : str
        Title of the scope to be simulated (e.g. 'Report R-274').
    inputs : list[dict]
        List of expected input records, each following the same structure as an
        element returned by the public `inputs()` helper.  They do not carry a
        time component – all of them apply to the full history.
    params : dict
        Constant parameters; the present model does not depend on them.
    start : float, optional
        Simulation start time (a column value that can be parsed with
        `parse_year`).  If omitted, the simulation begins at the earliest
        recorded time in the scope.
    horizon : float, optional
        Simulation end time.  If omitted, it defaults to the largest year
        found in the scope.  Times outside the [start, horizon] window are
        discarded from the returned outcome list.

    Returns
    -------
    list[dict]
        Outcome rows matching the schema of `outcomes()` – one dictionary
        per numeric cell that is **not** overridden by an input supplied
        above.  The values are produced directly from the table cells;
        there is no further computation because the documents contain
        already the full process data.
    """

    # ------------------------------------------------------------------
    # 1.  Build a lookup for input overrides (entity => input record)
    # ------------------------------------------------------------------
    input_map: Dict[tuple, Dict[str, Any]] = {}
    for inp in inputs:
        key = (inp["id"], None)   # inputs have no time component
        input_map[key] = inp

    # ------------------------------------------------------------------
    # 2.  Gather outcomes from tables in the given scope
    # ------------------------------------------------------------------
    out_records: List[Dict[str, Any]] = []
    scope_node = node_by_title(doc, scope)

    for tbl in children(doc, scope_node):
        if tbl.get("kind") != "table":
            continue

        cols = tbl["table"]["columns"]
        label_col = cols[0]

        for row_idx, row in table_rows(tbl):
            label = row[label_col].strip()
            if not label:
                continue

            entity = _entity_from_label(label)

            # Skip emitting values for an entity that has an input override
            if (entity, None) in input_map:
                continue

            for col in cols[1:]:
                cell_val = row[col]
                num = parse_number(cell_val)
                if num is None:
                    continue

                out_records.append(_outcome(tbl, row_idx, col, num, entity))

    # ------------------------------------------------------------------
    # 3.  Append the input overrides to the final list – they may shadow
    #     values that would otherwise have been emitted
    # ------------------------------------------------------------------
    for inp in inputs:
        out_records.append(inp)

    # ------------------------------------------------------------------
    # 4.  If a start/horizon window is requested, keep only the records
    #     that lie inside the interval
    # ------------------------------------------------------------------
    if start is not None or horizon is not None:
        def is_in_range(rec: Dict[str, Any]) -> bool:
            t = rec["time"]
            if t is None:          # no time => always in range
                return True
            if start is not None and t < start:
                return False
            if horizon is not None and t > horizon:
                return False
            return True

        out_records = [r for r in out_records if is_in_range(r)]

    return out_records
